import json, subprocess, math

base='/bench/arm/input/skill_call.py'

def call(skill,args):
    out=subprocess.check_output(['python3',base,skill,json.dumps(args)], text=True)
    return json.loads(out)

cobra=call('merged-taxon-occurrence-search', {'region':'EBTL','entity':'Indian cobra','radius_km':75})
ele=call('merged-taxon-occurrence-search', {'region':'EBTL','entity':'Asian elephant','radius_km':75})

crows=cobra['execution']['value']['rows']
erows=ele['execution']['value']['rows']

R=6371.0088

def hav(lat1, lon1, lat2, lon2):
    p1=math.radians(lat1); p2=math.radians(lat2)
    dphi=math.radians(lat2-lat1)
    dl=math.radians(lon2-lon1)
    a=math.sin(dphi/2)**2+math.cos(p1)*math.cos(p2)*math.sin(dl/2)**2
    return 2*R*math.asin(math.sqrt(a))

pairs=[]
minpair=None
cobra_hits=[]
ele_hits=[]
for ci,c in enumerate(crows):
    best=None
    for ei,e in enumerate(erows):
        d=hav(c['lat'],c['lon'],e['lat'],e['lon'])
        if best is None or d<best[0]:
            best=(d,ei,e)
        if minpair is None or d<minpair[0]:
            minpair=(d,ci,c,ei,e)
        if d<=10:
            pairs.append((d,ci,ei,c,e))
    if best and best[0]<=10:
        cobra_hits.append((best[0],ci,c,best[1],best[2]))

for ei,e in enumerate(erows):
    best=None
    for ci,c in enumerate(crows):
        d=hav(c['lat'],c['lon'],e['lat'],e['lon'])
        if best is None or d<best[0]:
            best=(d,ci,c)
    if best and best[0]<=10:
        ele_hits.append((best[0],ei,e,best[1],best[2]))

pairs.sort(key=lambda x:x[0])
cobra_hits.sort(key=lambda x:x[0])
ele_hits.sort(key=lambda x:x[0])

summary={
    'cobra_records': len(crows),
    'elephant_records': len(erows),
    'cobra_records_with_elephant_within_10km': len(cobra_hits),
    'elephant_records_with_cobra_within_10km': len(ele_hits),
    'total_cobra_elephant_pairs_within_10km': len(pairs),
    'minimum_distance_km': round(minpair[0],3),
    'closest_pair': {
        'cobra_id': minpair[2]['id'], 'cobra_lat': minpair[2]['lat'], 'cobra_lon': minpair[2]['lon'], 'cobra_time': minpair[2].get('time'), 'cobra_source': minpair[2].get('source'),
        'elephant_id': minpair[4]['id'], 'elephant_lat': minpair[4]['lat'], 'elephant_lon': minpair[4]['lon'], 'elephant_time': minpair[4].get('time'), 'elephant_source': minpair[4].get('source')
    },
    'sample_cobra_hits': [
        {
